import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import UnifiedNavbar from "../components/UnifiedNavbar";
import API from "../services/api";
import attendanceService from "../services/attendanceService";

function StaffDashboard() {
  const [stats, setStats] = useState({ todayPresent: 0, todayAbsent: 0, todayLeave: 0, totalStudents: 0 });
  const [loading, setLoading] = useState(true);
  const [todayLeaves, setTodayLeaves] = useState([]);

  const todayLabel = new Date().toLocaleDateString("en-IN", { weekday: "long", year: "numeric", month: "long", day: "numeric" });
  const today      = new Date().toISOString().split("T")[0];

  useEffect(() => {
    const fetchStats = async () => {
      try {
        setLoading(true);

        const studentsRes    = await API.get("/student");
        const studentsList   = studentsRes.data || [];

        const attendanceData = await attendanceService.getAttendance({ date: today });
        const todayAtt       = Array.isArray(attendanceData) ? attendanceData : [];

        setStats({
          totalStudents: studentsList.length,
          todayPresent:  todayAtt.filter(a => a.status === "Present").length,
          todayAbsent:   todayAtt.filter(a => a.status === "Absent").length,
          todayLeave:    todayAtt.filter(a => a.status === "Leave").length,
        });

        // Fetch approved leaves active today
        try {
          const leavesRes = await fetch("http://localhost:5155/api/leave?status=Approved");
          if (leavesRes.ok) {
            const allLeaves = await leavesRes.json();
            const active = allLeaves.filter(l => {
              const from = new Date(l.fromDate);
              const to   = new Date(l.toDate);
              const now  = new Date(today);
              return now >= from && now <= to;
            });
            setTodayLeaves(active);
          }
        } catch { /* ignore */ }

      } catch { /* ignore */ } finally {
        setLoading(false);
      }
    };
    fetchStats();
  }, [today]);

  return (
    <div className="dashboard">
      <UnifiedNavbar />

      <div className="main-content">

        {/* Welcome banner */}
        <div style={{
          background:   "var(--color-brand-gradient)",
          borderRadius: "var(--radius-xl)",
          padding:      "var(--space-8) var(--space-10)",
          marginBottom: "var(--space-8)",
          position:     "relative",
          overflow:     "hidden",
        }}>
          <div style={{ position:"absolute", right:"-40px", top:"-40px", width:"180px", height:"180px", borderRadius:"50%", background:"rgba(255,255,255,0.08)", pointerEvents:"none" }} />
          <div style={{ position:"absolute", right:"60px", bottom:"-60px", width:"140px", height:"140px", borderRadius:"50%", background:"rgba(255,255,255,0.06)", pointerEvents:"none" }} />
          <div style={{ position:"relative", zIndex:1 }}>
            <div style={{ fontSize:"var(--text-sm)", color:"rgba(255,255,255,0.8)", fontWeight:"var(--font-medium)", marginBottom:"var(--space-1)" }}>
              Welcome back 👋
            </div>
            <div style={{ fontSize:"var(--text-3xl)", fontFamily:"var(--font-display)", fontWeight:"var(--font-bold)", color:"white", letterSpacing:"-0.02em", lineHeight:"var(--leading-tight)", marginBottom:"var(--space-2)" }}>
              Staff Dashboard
            </div>
            <div style={{ fontSize:"var(--text-xs)", color:"rgba(255,255,255,0.65)" }}>
              {todayLabel}
            </div>
          </div>
        </div>

        {/* Today's quick stats */}
        <div style={{
          display:             "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))",
          gap:                 "var(--space-4)",
          marginBottom:        "var(--space-8)",
        }}>
          {[
            { label: "Total Students", value: stats.totalStudents, color: "var(--color-accent-blue)"  },
            { label: "Present Today",  value: stats.todayPresent,  color: "var(--color-success)"      },
            { label: "Absent Today",   value: stats.todayAbsent,   color: "var(--color-danger)"       },
            { label: "On Leave",       value: stats.todayLeave,    color: "var(--color-warning)"      },
          ].map((s) => (
            <div key={s.label} style={{
              background:   "var(--color-surface)",
              border:       "1px solid var(--color-border)",
              borderRadius: "var(--radius-lg)",
              padding:      "var(--space-5)",
              boxShadow:    "var(--shadow-xs)",
            }}>
              <div style={{ fontSize:"1.75rem", fontWeight:"var(--font-bold)", color:s.color, lineHeight:1.1, letterSpacing:"-0.02em" }}>
                {loading ? "—" : s.value}
              </div>
              <div style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", color:"var(--color-text-tertiary)", textTransform:"uppercase", letterSpacing:"0.06em", marginTop:"var(--space-1)" }}>
                {s.label}
              </div>
            </div>
          ))}
        </div>

        {/* Today's Approved Leaves */}
        {todayLeaves.length > 0 && (
          <div style={{
            background:    "var(--color-surface)",
            border:        "1px solid #FCD34D",
            borderRadius:  "var(--radius-xl)",
            padding:       "var(--space-6)",
            marginBottom:  "var(--space-8)",
            boxShadow:     "0 4px 16px rgba(217,119,6,0.1)",
          }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"var(--space-5)" }}>
              <div style={{ display:"flex", alignItems:"center", gap:"var(--space-3)" }}>
                <div style={{ width:"36px", height:"36px", borderRadius:"var(--radius-md)", background:"#FEF3C7", display:"flex", alignItems:"center", justifyContent:"center", fontSize:"1.2rem" }}>
                  📋
                </div>
                <div>
                  <h3 style={{ fontSize:"var(--text-base)", fontWeight:"var(--font-bold)", color:"var(--color-text-primary)", marginBottom:"2px" }}>
                    On Leave Today
                  </h3>
                  <p style={{ fontSize:"var(--text-xs)", color:"var(--color-text-tertiary)" }}>
                    {todayLeaves.length} approved leave{todayLeaves.length !== 1 ? "s" : ""} active today
                  </p>
                </div>
              </div>
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:"var(--space-2)" }}>
              {todayLeaves.map(l => (
                <div key={l.id} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"var(--space-3) var(--space-4)", background:"#FFFBEB", borderRadius:"var(--radius-lg)", border:"1px solid #FDE68A" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:"var(--space-3)" }}>
                    <div style={{ width:"32px", height:"32px", borderRadius:"var(--radius-full)", background:"#FEF3C7", display:"flex", alignItems:"center", justifyContent:"center", fontSize:"var(--text-xs)", fontWeight:"var(--font-bold)", color:"#D97706" }}>
                      {(l.userName || "?")[0].toUpperCase()}
                    </div>
                    <div>
                      <div style={{ fontSize:"var(--text-sm)", fontWeight:"var(--font-semibold)", color:"var(--color-text-primary)" }}>{l.userName}</div>
                      <div style={{ fontSize:"var(--text-xs)", color:"var(--color-text-tertiary)" }}>{l.userRole} • {l.leaveType}</div>
                    </div>
                  </div>
                  <div style={{ textAlign:"right" }}>
                    <div style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", color:"#D97706" }}>
                      {l.fromDate} → {l.toDate}
                    </div>
                    <span style={{ fontSize:"9px", background:"#FEF3C7", color:"#D97706", padding:"1px 8px", borderRadius:"var(--radius-full)", fontWeight:"var(--font-bold)", textTransform:"uppercase" }}>
                      Approved
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Action cards */}
        <div className="cards">

          <div className="card">
            <h3>Manage Menu</h3>
            <p style={{ color:"var(--color-text-secondary)", fontSize:"var(--text-sm)", margin:"var(--space-3) 0 var(--space-4)", lineHeight:"var(--leading-relaxed)" }}>
              Create, edit, and delete daily menu items
            </p>
            <Link to="/edit-menu" className="card-link">Go to Menu Management →</Link>
          </div>

          <div className="card">
            <div style={{ position:"absolute", top:0, left:0, right:0, height:"3px", background:"linear-gradient(90deg,#16A34A,#22C55E)", borderRadius:"var(--radius-lg) var(--radius-lg) 0 0" }} />
            <h3>Mark Attendance</h3>
            <p style={{ color:"var(--color-text-secondary)", fontSize:"var(--text-sm)", margin:"var(--space-3) 0 var(--space-2)", lineHeight:"var(--leading-relaxed)" }}>
              Mark and track student attendance for today
            </p>
            <div style={{ display:"flex", gap:"var(--space-2)", margin:"var(--space-3) 0 var(--space-4)", flexWrap:"wrap" }}>
              <span style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", padding:"3px 10px", borderRadius:"var(--radius-full)", background:"var(--color-success-light)", color:"var(--color-success-dark)" }}>
                ✓ {loading ? "—" : stats.todayPresent} Present
              </span>
              <span style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", padding:"3px 10px", borderRadius:"var(--radius-full)", background:"var(--color-danger-light)", color:"var(--color-danger-dark)" }}>
                ✗ {loading ? "—" : stats.todayAbsent} Absent
              </span>
              <span style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", padding:"3px 10px", borderRadius:"var(--radius-full)", background:"var(--color-warning-light)", color:"var(--color-warning-dark)" }}>
                📋 {loading ? "—" : stats.todayLeave} Leave
              </span>
            </div>
            <Link to="/attendance" className="card-link">Mark Attendance →</Link>
          </div>

          <div className="card">
            <h3>Today's Menu</h3>
            <p style={{ color:"var(--color-text-secondary)", fontSize:"var(--text-sm)", margin:"var(--space-3) 0 var(--space-4)", lineHeight:"var(--leading-relaxed)" }}>
              View today's meal plan for students
            </p>
            <Link to="/today-menu" className="card-link">View Today's Menu →</Link>
          </div>

        </div>
      </div>
    </div>
  );
}

export default StaffDashboard;
